import React, { useState } from 'react';
import ErrorCases from '@/components/ErrorCases';
import useSessionState from '@/hooks/useSessionState';
import { Alert, Button, Card, Drawer, Select, Space, Table, Tag } from 'antd';
import { Chart, PageHeading, ResourceState, Source, useResource, type ResearchData } from '@/components/Research';
import { MODEL_LABELS, type ModelId } from '@/types/ecg';
import { pct, CLASS_COLORS } from '@/design';

export default function Generalization() {
  const resource=useResource<ResearchData>('/api/research/summary');
  const [model,setModel]=useSessionState<ModelId>('general.model','cnn_1d'); const [label,setLabel]=useSessionState('general.class','all'); const [subject,setSubject]=useSessionState('general.subject','all');
  const [direction,setDirection]=useState<string>();const [detail,setDetail]=useState<string>();const [strategy,setStrategy]=useState('unweighted');
  if(!resource.data) return <div className="research-page"><ResourceState {...resource} /></div>;
  const data=resource.data; const subjects=data.subjects.filter(r=>r.dataset==='N/S/V/F' && (subject==='all'||r.subject_id===subject));
  const labels=label==='all'?['N','S','V','F']:[label];
  const cells=subjects.flatMap((r,y)=>labels.map((l,x)=>[x,y,Math.log10(Number(r[l])+1),Number(r[l])]));
  const errors=data.confusion.filter(r=>r.task==='N/S/V/F'&&r.model===model&&r.true_class!==r.predicted_class&&(label==='all'||r.true_class===label)).sort((a,b)=>Number(b.count)-Number(a.count));
  const concentration=data.concentration.filter(r=>r.dataset==='N/S/V/F'&&['S','F'].includes(r.class));
  return <div className="research-page"><PageHeading title="错误与泛化分析" description="从患者分布、错误方向和已有消融实验解释模型局限。" />
    <Alert type="warning" showIcon title="少数类的患者集中度限制跨患者泛化" description="四分类 F / S 支持量稀疏；test 仅用于既有结果的描述性错误诊断，五折患者分组 CV 仅使用原 train + validation。" />
    <div className="filter-bar"><Space wrap><label>模型 <Select aria-label="分析模型" value={model} onChange={setModel} options={Object.entries(MODEL_LABELS).map(([value,label])=>({value,label}))} /></label><label>真实类别 <Select aria-label="分析类别" value={label} onChange={setLabel} options={['all','N','S','V','F'].map(value=>({value,label:value==='all'?'全部类别':value}))} /></label><label>受试者分布 <Select showSearch aria-label="分布受试者" value={subject} onChange={setSubject} style={{width:190}} options={[{value:'all',label:'全部受试者'},...data.subjects.filter(r=>r.dataset==='N/S/V/F').map(r=>({value:r.subject_id,label:r.subject_id.replace('subject_','')}))]} /></label></Space></div>
    <div className="research-grid"><Card title="受试者 × 类别支持量"><Chart onClick={e=>setDetail(subjects[e.value[1]].subject_id)} label="真实受试者类别热力图" height={Math.max(280,subjects.length*18+100)} option={{grid:{left:90,right:25,top:20,bottom:68},tooltip:{confine:true,formatter:(p:any)=>`${subjects[p.value[1]].subject_id}<br/>${labels[p.value[0]]} 类：${p.value[3]} 心拍<br/>受试者占比 ${(p.value[3]/Number(subjects[p.value[1]].total_samples)*100).toFixed(2)}%`},xAxis:{type:'category',data:labels},yAxis:{type:'category',data:subjects.map(r=>r.subject_id.replace('subject_','')),inverse:true,axisLabel:{fontSize:11}},visualMap:{min:0,max:4,orient:'horizontal',bottom:0,left:'center',text:['log10(n+1)','0'],inRange:{color:['#F5F7FA','#86BEFF','#142B49']}},series:[{type:'heatmap',data:cells}]}} /><p className="chart-insight">空白和浅色区域代表支持量很少；F 类无法在多数受试者上稳定评估。</p><Source>{data.sources.subjects}</Source></Card>
    <div className="stack"><Card title="四分类主要误分类方向"><Chart onClick={e=>setDirection(errors.slice(0,7).reverse()[e.dataIndex].true_class+'-'+errors.slice(0,7).reverse()[e.dataIndex].predicted_class)} label="四分类误分类计数" height={340} option={{grid:{left:72,right:40,top:24,bottom:32},xAxis:{type:'value',name:'心拍数'},yAxis:{type:'category',data:errors.slice(0,7).reverse().map(r=>`${r.true_class} → ${r.predicted_class}`)},series:[{type:'bar',barMaxWidth:26,data:errors.slice(0,7).reverse().map(r=>({value:Number(r.count),itemStyle:{color:CLASS_COLORS[r.true_class]}})),label:{show:true,position:'right'}}]}} /><p className="chart-insight">{errors.length?`${MODEL_LABELS[model]} 最大错误方向为 ${errors[0].true_class} → ${errors[0].predicted_class}，共 ${Number(errors[0].count).toLocaleString()} 拍。`:'当前筛选下无误分类条目。'}</p><Source>{data.sources.confusion}</Source></Card>
    <Card title="F / S 类最大受试者占比"><Chart label="各分区少数类集中度" height={300} option={{xAxis:{type:'category',data:concentration.map(r=>`${r.split} / ${r.class}`)},yAxis:{type:'value',max:100,name:'最大受试者占比 (%)'},series:[{type:'bar',barMaxWidth:35,data:concentration.map(r=>({value:Number(r.top_subject_share_pct),itemStyle:{color:CLASS_COLORS[r.class]}})),label:{show:true,position:'top',formatter:(p:any)=>`${p.value.toFixed(1)}%`}}]}} /><p className="chart-insight">test F 类 371 拍中的 370 拍来自同一受试者，分数对患者组成高度敏感。</p><Source>{data.sources.concentration}</Source></Card></div></div>
    <div className="research-grid"><Card title="类别权重消融 · Validation"><Chart label="真实权重消融验证指标" option={{legend:{top:0},xAxis:{type:'category',data:data.weights.filter(r=>r.split==='val').map(r=>r.strategy),axisLabel:{rotate:18,fontSize:11}},yAxis:{type:'value',max:1},grid:{left:50,right:20,top:40,bottom:76},series:['accuracy','macro_f1_present_classes'].map((key,i)=>({name:i?'Macro-F1':'Accuracy',type:'bar',itemStyle:{color:i?'#1677FF':'#94A8C1'},data:data.weights.filter(r=>r.split==='val').map(r=>Number(r[key]))}))}} /><p className="chart-insight">改变权重会改变类别召回和预测占比；本轮仅展示原消融结果，不重新选择模型。</p><Source>{data.sources.weights}</Source></Card>
    <Card title="五折患者分组 CV · train + validation"><Chart label="五折患者分组交叉验证" option={{legend:{top:0},xAxis:{type:'category',data:['Fold 1','Fold 2','Fold 3','Fold 4','Fold 5']},yAxis:{type:'value',min:0,max:1,name:'Macro-F1 (present classes)'},series:Object.entries(MODEL_LABELS).map(([id,name],i)=>({name,type:'line',symbolSize:8,itemStyle:{color:['#64748B','#13A2A2','#1677FF'][i]},data:data.cv.filter(r=>r.model===id).map(r=>Number(r.macro_f1_present_classes))}))}} /><p className="chart-insight">跨折波动说明患者组成会影响结果；CV 不是一次固定 test 结果的替代品。</p><Source>{data.sources.cv}</Source></Card></div>
    <div className="category-controls">{['N-S','F-N','F-V','V-N'].map(value=><Button key={value} onClick={()=>setDirection(value)}>{value.replace('-', ' → ')}</Button>)}</div>
    {direction&&<ErrorCases task="nsvf" model={model} trueLabel={direction.split('-')[0]} predictedLabel={direction.split('-')[1]} subject={subject==='all'?undefined:subject}/>}
    <Card title="验证集类别权重策略详情" className="spaced-card"><Select aria-label="权重策略" value={strategy} onChange={setStrategy} options={['unweighted','sqrt_inverse','capped_inverse_10','full_inverse'].map(value=>({value,label:value}))}/><Space style={{margin:'12px 0'}} wrap><Tag>Validation Accuracy {pct(data.weights.find(r=>r.split==='val'&&r.strategy===strategy)?.accuracy||0)}</Tag><Tag color="blue">Validation Macro-F1 {pct(data.weights.find(r=>r.split==='val'&&r.strategy===strategy)?.macro_f1_present_classes||0)}</Tag></Space><Table rowKey="class" pagination={false} size="small" scroll={{x:650}} dataSource={data.weight_classes.filter(r=>r.split==='val'&&r.strategy===strategy)} columns={[{title:'类别',dataIndex:'class'},{title:'Support',dataIndex:'support'},{title:'Precision',dataIndex:'precision',render:pct},{title:'Recall',dataIndex:'recall',render:pct},{title:'F1',dataIndex:'f1',render:pct},{title:'预测数量',dataIndex:'predicted_count'},{title:'预测占比 (%)',dataIndex:'predicted_share_pct',render:(v:string)=>Number(v).toFixed(2)}]}/><Chart label="选中权重策略的类别预测分布" height={220} option={{xAxis:{type:'category',data:['N','S','V','F']},yAxis:{type:'value',name:'心拍数'},series:[{type:'bar',barMaxWidth:40,data:data.weight_classes.filter(r=>r.split==='val'&&r.strategy===strategy).map(r=>({value:Number(r.predicted_count),itemStyle:{color:CLASS_COLORS[r.class]}}))}]}}/></Card>
    <Drawer title={`${detail||''} · 真实类别统计`} open={Boolean(detail)} onClose={()=>setDetail(undefined)} size={480}>{detail&&<Table rowKey="class" pagination={false} dataSource={['N','S','V','F'].map(label=>({class:label,count:Number(data.subjects.find(r=>r.dataset==='N/S/V/F'&&r.subject_id===detail)?.[label]||0)}))} columns={[{title:'类别',dataIndex:'class'},{title:'有效心拍数',dataIndex:'count'}]}/>}<h4>已有四分类 test 结果</h4><Table rowKey="model" size="small" pagination={false} dataSource={data.subject_metrics.filter(r=>r.task==='N/S/V/F'&&r.subject_id===detail)} columns={[{title:'模型',dataIndex:'model'},{title:'Accuracy',dataIndex:'accuracy',render:pct},{title:'Macro-F1 (present classes)',dataIndex:'macro_f1_present_classes',render:pct}]}/><p>未出现在 test 分区的受试者没有对应 test 指标，不补造结果。</p><Button onClick={()=>{if(detail)setSubject(detail);setDetail(undefined);}}>按此受试者筛选</Button></Drawer>
    <Card title={`${MODEL_LABELS[model]} · 五折验证支持量`}><Table rowKey="fold" pagination={false} scroll={{x:650}} dataSource={data.cv.filter(r=>r.model===model)} columns={[{title:'Fold',dataIndex:'fold'},{title:'受试者数',dataIndex:'validation_subject_count'},{title:'Accuracy',dataIndex:'accuracy',render:pct},{title:'Macro-F1',dataIndex:'macro_f1_present_classes',render:pct},...['N','S','V','F'].map(l=>({title:`${l} support`,dataIndex:`support_${l}`}))]} /></Card>
  </div>;
}

